  if (!d.facing) {
    let total = d.street === 'flop' ? NUTS_FLOP_BET[n.role][feature][['high', 'mid', 'low'].indexOf(texture.split('_')[1])]
      : NUTS_LATER_BET[d.street][d.players][d.line][d.activePosition];
    if (d.street !== 'flop' && d.sprBand === 'shallow') total += 3;
    if (d.street !== 'flop' && feature === 'pair') total -= 3; // protect checks; current nuts is NOT downgraded as a weak shared hand
    total = bounded(total); mix.check = 100 - total;
    if (n.actions.includes('allin')) {
      if (d.sprBand === 'shallow') mix.allin = total;
      else [mix.bet33, mix.allin] = allocate(total, d.players === 3 ? [30, 70] : [22, 78]);
    } else {
      const shares = [...NUTS_SIZES[d.street][feature]];
      if (d.street === 'flop' && n.role === 'first' || d.street !== 'flop' && d.line === 'defender' && d.activePosition !== 'last') {
        shares[1] += shares[2]; shares[2] = 0;
      }
      [mix.bet33, mix.bet75, mix.bet125] = allocate(total, shares);
    }
    return mix;
  }
  const [continueByPrice, raiseAnchor] = NUTS_RESPONSE[d.street][n.facing];
  let continued = continueByPrice[PRICE_ORDER.indexOf(d.priceBand)], raised = raiseAnchor;
  if (d.street !== 'river' && d.priceBand === 'expensive' && d.players === 3 && n.pendingBehind &&
      ['raise1', 'raise2', 'allin'].includes(n.facing) && ['wet', 'straight'].includes(feature)) continued -= 2;
  if (d.players === 3) raised -= n.pendingBehind ? 12 : 5; // allow the other player to continue with worse
  else raised += 4;
  if (d.activePosition === 'last') raised += 3;
  if (d.responseType === 'invested') raised += 5;
  if (d.sprBand === 'shallow') raised += 8;
  if (['paired', 'pair'].includes(feature)) raised -= 8;
  if (feature === 'monotone') raised -= 5;
  raised = n.actions.includes('raise') ? Math.min(continued, bounded(raised)) : 0;
  mix.fold = 100 - continued; mix.call = continued - raised;
  if (n.actions.includes('raise')) mix.raise = raised;
  return mix;
}

// Publicly locked boards: every compatible holding ties. Avoid rake-building
// aggression and never fold the guaranteed share of the existing pot.
function boardLockedMix(d) {
  const actions = describeMw3Node(d.node).actions, mix = Object.fromEntries(actions.map(action => [action, 0]));
  mix[d.facing ? 'call' : 'check'] = 100;
  return mix;
}
// Unlocked river boards played without private improvement are NOT value hands.
// These direct call rates are conservative bluff-catching judgments. They cannot
// distinguish a shared high-card from a shared full house under the present
// one-runout-feature schema; that material quality limitation remains explicit.
const BOARD_SHARED_CALL = {
  2: { 33: [67, 45, 30], 75: [49, 27, 17], 125: [32, 13, 5], raise1: [27, 11, 3], raise2: [20, 6, 1], allin: [34, 14, 5] },
  3: { 33: [48, 30, 16], 75: [30, 14, 6], 125: [18, 6, 1], raise1: [15, 5, 1], raise2: [10, 2, 0], allin: [22, 7, 1] },
};
function boardSharedMix(d, texture) {
  const n = describeMw3Node(d.node), mix = Object.fromEntries(n.actions.map(action => [action, 0]));
  if (!d.facing) { mix.check = 100; return mix; }
  // The class cannot occur before the river; retain explicit safe schema rows.
  if (d.street !== 'river') { mix.fold = 100; return mix; }
  let call = BOARD_SHARED_CALL[d.players][n.facing][PRICE_ORDER.indexOf(d.priceBand)];
  if (d.players === 3 && !n.pendingBehind) call -= 4; // another live player has already continued
  if (d.responseType === 'invested') call += 3;
  if (d.line === 'defender') call -= 2;
  if (d.line === 'aggressor') call += 2;
  if (texture === 'flush') call -= 3;
  if (texture === 'straight') call -= 2;
  mix.call = bounded(call); mix.fold = 100 - mix.call;
  return mix;
}
// V4: certified private no-loss hands, with ties possible. On flop/turn the
// classifier admits royal OR a current >=full-house nuts with a sufficient
// all-future-opponent rank bound. River remains private royal ONLY, preserving
// the V3 river profile and all other river current-nuts frequencies.
// The author re-reviewed and retained these V3 numerical mixes: early-street
// calls protect third-player value / split-pot efficiency, and raises can earn
// value from worse holdings. No-loss does not mean every opponent must chop.
// Free cards cannot beat a certified hand, but may turn a sole win into a tie.
// Do not extend this class to generic quads/straight flushes without the proof.
const ABSOLUTE_FLOP_BET = { first: 28, middle: 62, last: 80 };
const ABSOLUTE_FLOP_SIZES = { first: [75, 25, 0], middle: [65, 35, 0], last: [55, 45, 0] };
const ABSOLUTE_LATER_BET = {
  turn: {
    3: { checked: { first: 46, middle: 61, last: 84 }, aggressor: { first: 78, middle: 86, last: 93 }, defender: { first: 22, middle: 26, last: 73 } },
    2: { checked: { first: 60, last: 89 }, aggressor: { first: 86, last: 95 }, defender: { first: 25, last: 81 } },
  },
  river: {
    3: { checked: { first: 83, middle: 90, last: 99 }, aggressor: { first: 97, middle: 99, last: 100 }, defender: { first: 44, middle: 48, last: 96 } },
    2: { checked: { first: 90, last: 100 }, aggressor: { first: 99, last: 100 }, defender: { first: 52, last: 99 } },
  },
};
const ABSOLUTE_LATER_SIZES = {
  turn: { blank: [35, 55, 10], over: [40, 50, 10], pair: [50, 45, 5], straight: [30, 60, 10], flush: [25, 60, 15] },
  river: { blank: [15, 65, 20], over: [20, 60, 20], pair: [30, 60, 10], straight: [15, 60, 25], flush: [10, 60, 30] },
};
const ABSOLUTE_RAISE = {
  flop: { 33: 48, 75: 56, 125: 62, raise1: 66, raise2: 0, allin: 0 },
  turn: { 33: 62, 75: 72, 125: 82, raise1: 88, raise2: 0, allin: 0 },
  river: { 33: 88, 75: 95, 125: 100, raise1: 100, raise2: 0, allin: 0 },
};
function absoluteNutsMix(d, texture) {
  const n = describeMw3Node(d.node), mix = Object.fromEntries(n.actions.map(action => [action, 0]));
  if (!d.facing) {
    let total = d.street === 'flop' ? ABSOLUTE_FLOP_BET[n.role]
      : ABSOLUTE_LATER_BET[d.street][d.players][d.line][d.activePosition];
    if (d.street !== 'flop' && d.sprBand === 'shallow') total += 4;
    total = bounded(total); mix.check = 100 - total;
    if (n.actions.includes('allin')) {
      if (d.sprBand === 'shallow') mix.allin = total;
      else [mix.bet33, mix.allin] = allocate(total, d.players === 3 ? [35, 65] : [25, 75]);
    } else {
      const shares = d.street === 'flop' ? ABSOLUTE_FLOP_SIZES[n.role] : ABSOLUTE_LATER_SIZES[d.street][texture];
      [mix.bet33, mix.bet75, mix.bet125] = allocate(total, shares);
    }
    return mix;
  }
  let raised = ABSOLUTE_RAISE[d.street][n.facing];
  if (d.players === 3) raised -= d.street === 'flop' ? n.pendingBehind ? 16 : 10
    : d.street === 'turn' ? n.pendingBehind ? 10 : 6 : n.pendingBehind ? 5 : 2;
  else if (d.street !== 'river') raised += 3;
  if (d.street !== 'river') {
    if (d.responseType === 'invested') raised += 5;
    if (d.priceBand === 'cheap') raised -= d.street === 'flop' ? 5 : 3;
    if (d.priceBand === 'expensive') raised += 4;
    if (d.sprBand === 'shallow') raised += 10;
    if (d.sprBand === 'deep') raised -= 5;
  }
  raised = n.actions.includes('raise') ? bounded(raised) : 0;
  mix.fold = 0; mix.call = 100 - raised;
  if (n.actions.includes('raise')) mix.raise = raised;
  return mix;
}

function authoredMix(d, tier, texture) {
  if (tier === 'board_locked') return boardLockedMix(d);
  if (tier === 'board_shared') return boardSharedMix(d, texture);
  if (tier === 'absolute_nuts') return absoluteNutsMix(d, texture);
  if (tier === 'nuts') return nutsMix(d, texture);
  return d.facing ? responseMix(d, tier, texture) : firstMix(d, tier, texture);
}

// Defaults are explicit schema safety coverage, not a runtime strategy substitute.
// The exhaustive current-geometry exact-context overrides below are selected in
// preference to ALL of them; audits must verify no observed context uses priority 0.
function fallbackDecision(node) {
  const n = describeMw3Node(node), facing = n.facing !== null;
  return { node, street: n.street, role: n.role, facing, players: 3, activePosition: n.role,
    line: n.street === 'flop' ? 'checked' : 'defender', responseType: facing ? 'cold' : 'none',
    priceBand: facing ? ['125', 'allin', 'raise2'].includes(n.facing) ? 'expensive' : 'standard' : 'none',
    sprBand: n.situation.endsWith('low_spr') || n.facing === 'allin' ? 'shallow' : 'deep' };
}

export function buildMw3PilotPolicies(inputs, probe) {
  if (inputs?.spot?.id !== MW3_PILOT_AUTHORSHIP.spotId || inputs.fingerprint !== MW3_PILOT_AUTHORSHIP.sourceFingerprint ||
      inputs.spot.seats.join() !== 'BB,CO,BTN' || inputs.spot.potBb !== 8 || inputs.spot.stackBb !== 97.5) {
    throw new Error('MW3 pilot authoring is pinned to the reviewed CO / BTN / BB inputs; re-author changed sources');
  }
  if (!probe?.nodes || !probe.contexts || Object.keys(probe.nodes).length !== 117 || Object.keys(probe.contexts).length !== 1209) {
    throw new Error('MW3 pilot authoring requires the complete reviewed 117-node / 1209-context probe');
  }
  const flop = { version: 3, kind: 'ai_estimate_not_gto', spot_id: inputs.spot.id, streets: ['flop'], rules: [] };
  const later = { version: 3, kind: 'ai_estimate_not_gto', spot_id: inputs.spot.id, streets: ['turn', 'river'], rules: [] };
  for (const node of Object.keys(probe.nodes).sort()) {
    const d = fallbackDecision(node), policy = d.street === 'flop' ? flop : later;
    for (const tier of TIERS) policy.rules.push({ node, tier, when: mw3AnySelector(), priority: 0,
      mix: authoredMix(d, tier, d.street === 'flop' ? 'monotone_high' : 'flush') });
  }
  for (const [key, d] of Object.entries(probe.contexts).sort(([a], [b]) => a.localeCompare(b))) {
    if (key !== mw3PolicyContextKey(d) || !probe.nodes[d.node]) throw new Error('Invalid MW3 authoring context');
    const policy = d.street === 'flop' ? flop : later;
    for (const texture of d.street === 'flop' ? FLOP_TEXTURES : LATER_TEXTURES) for (const tier of TIERS) {
      policy.rules.push({ node: d.node, tier, when: { line: d.line, texture, players: d.players,
        position: d.activePosition, response: d.responseType, price: d.priceBand, spr: d.sprBand },
      priority: 100, mix: authoredMix(d, tier, texture) });
    }
  }
  validateMw3Policy(flop, { spotId: inputs.spot.id, nodes: probe.nodes });
  validateMw3Policy(later, { spotId: inputs.spot.id, nodes: probe.nodes });
  return { flop, later };
}
